msg.method = "POST";
msg.headers = { "Content-Type": "application/json" };
msg.payload = { idToken: msg.payload.credential };

return [msg, null];

const res = msg.payload;

if (res.error || !res.users || res.users.length === 0) {
    msg.statusCode = 401;
    msg.payload = { success: false, message: "Geçersiz Google Token'ı." };
    return [null, msg];
}

const googleUser = res.users[0];
msg.googleUser = googleUser;

